const RESET_TOKEN_TTL_MINUTES = 30;

type PasswordResetToken = { userId: string; expiresAt: number };

// Keyed by SHA-256 of the token, so a leaked store can't be replayed as reset links.
const passwordResetTokens = new Map<string, PasswordResetToken>();
const passwordHashes = new Map<string, string>();

function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;
}

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }

  const user: User = {
    id: randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // A failed welcome email shouldn't fail the signup.
  try {
    await sendWelcomeEmail(user);
  } catch (err) {
    console.error(`Failed to send welcome email to user ${user.id}`, err);
  }

  return user;
}

// Always resolves the same way whether or not the email exists, so callers
// can't use it to discover which addresses have accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email === email.trim().toLowerCase());
  if (!user) return;

  // Only the newest link for a user stays valid.
  for (const [key, entry] of passwordResetTokens) {
    if (entry.userId === user.id) passwordResetTokens.delete(key);
  }

  const token = randomBytes(32).toString("base64url");
  passwordResetTokens.set(hashToken(token), {
    userId: user.id,
    expiresAt: Date.now() + RESET_TOKEN_TTL_MINUTES * 60_000,
  });

  try {
    await sendPasswordResetEmail(user, token, RESET_TOKEN_TTL_MINUTES);
  } catch (err) {
    console.error(`Failed to send password reset email to user ${user.id}`, err);
  }
}

export async function resetPassword(token: string, newPassword: string): Promise<User> {
  if (newPassword.length < 8) {
    throw new Error("Password must be at least 8 characters");
  }

  const key = hashToken(token);
  const entry = passwordResetTokens.get(key);
  if (!entry || entry.expiresAt < Date.now()) {
    passwordResetTokens.delete(key);
    throw new Error("This reset link is invalid or has expired");
  }

  const user = users.find((u) => u.id === entry.userId);
  if (!user) {
    passwordResetTokens.delete(key);
    throw new Error("This reset link is invalid or has expired");
  }

  passwordResetTokens.delete(key);
  passwordHashes.set(user.id, hashPassword(newPassword));
  return user;
}
